actions.script:
import java.math.BigDecimal
import java.math.RoundingMode

def wagesCeiling = config?.wagesCeiling ?: new BigDecimal("15000")
def pensionCeiling = config?.pensionWagesCeiling ?: new BigDecimal("15000")
def empPercent = config?.employeeContributionPercent ?: new BigDecimal("12")
def erPercent = config?.employerContributionPercent ?: new BigDecimal("12")
def pensionPercent = config?.pensionFundPercent ?: new BigDecimal("8.33")
def adminPercent = config?.epfAdminChargesPercent ?: new BigDecimal("0.50")
def edliPercent = config?.edliChargesPercent ?: new BigDecimal("0.50")

// EPF wages = min(basic, wages ceiling) unless employee opts for full basic
epfWages = basicPay.min(wagesCeiling)
if (empStat?.pfWages) epfWages = empStat.pfWages.min(basicPay)

// Employee contribution: 12% of EPF wages
employeeContribution = epfWages.multiply(empPercent)
    .divide(new BigDecimal("100"), 0, RoundingMode.HALF_UP)

// Voluntary PF addition
if (empStat?.voluntaryPfPercent && empStat.voluntaryPfPercent > 0) {
    def vpf = basicPay.multiply(empStat.voluntaryPfPercent)
        .divide(new BigDecimal("100"), 0, RoundingMode.HALF_UP)
    employeeContribution = employeeContribution.add(vpf)
}

// Employer pension: 8.33% of min(basic, pensionCeiling)
def pensionWages = basicPay.min(pensionCeiling)
employerPensionAmount = pensionWages.multiply(pensionPercent)
    .divide(new BigDecimal("100"), 0, RoundingMode.HALF_UP)

// Employer PF = 12% - 8.33% = 3.67% of EPF wages
def erPfPercent = erPercent.subtract(pensionPercent)
employerPfAmount = epfWages.multiply(erPfPercent)
    .divide(new BigDecimal("100"), 0, RoundingMode.HALF_UP)

// Admin charges on EPF wages
adminCharges = epfWages.multiply(adminPercent)
    .divide(new BigDecimal("100"), 0, RoundingMode.HALF_UP)

// EDLI charges on EPF wages
edliCharges = epfWages.multiply(edliPercent)
    .divide(new BigDecimal("100"), 0, RoundingMode.HALF_UP)

totalEmployerCost = employerPfAmount.add(employerPensionAmount).add(adminCharges).add(edliCharges)

import java.math.BigDecimal
import java.math.RoundingMode

def ceiling = config?.grossWagesCeiling ?: new BigDecimal("21000")
def empPercent = config?.employeeContributionPercent ?: new BigDecimal("0.75")
def erPercent = config?.employerContributionPercent ?: new BigDecimal("3.25")

if (grossPay.compareTo(ceiling) <= 0) {
    isApplicable = true
    employeeContribution = grossPay.multiply(empPercent)
        .divide(new BigDecimal("100"), 0, RoundingMode.CEILING)
    employerContribution = grossPay.multiply(erPercent)
        .divide(new BigDecimal("100"), 0, RoundingMode.CEILING)
} else {
    isApplicable = false
    employeeContribution = BigDecimal.ZERO
    employerContribution = BigDecimal.ZERO
}
